{
  "overall_decision": "manual_review",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0002",
          "reason": "Formal constitutional authority baseline only; it defines Marcos's powers but is not Marcos-specific existential-risk conduct."
        },
        {
          "evidence_id": "E0003",
          "reason": "Term-limit baseline only; it constrains tenure but does not show any ruler-attributed risk-reducing choice."
        },
        {
          "evidence_id": "E0004",
          "reason": "Territorial non-nuclear policy is inherited legal context, not Marcos conduct."
        },
        {
          "evidence_id": "E0005",
          "reason": "IAEA safeguards status is inherited treaty context, not a 2022 Marcos action."
        },
        {
          "evidence_id": "E0006",
          "reason": "NPT ratification predates Marcos and should not be read as his own restraint."
        },
        {
          "evidence_id": "E0007",
          "reason": "TPNW ratification predates Marcos and is baseline context only."
        },
        {
          "evidence_id": "E0008",
          "reason": "Bangkok Treaty membership is regional baseline, not ruler-attributed existential-risk governance."
        },
        {
          "evidence_id": "E0009",
          "reason": "Inherited civilian nuclear policy under Duterte is pre-Marcos context, not Marcos's own 2022 decision."
        },
        {
          "evidence_id": "E0010",
          "reason": "This is a strategy statement about nuclear power, not a demonstrated safeguard, command-control, or catastrophe-prevention action."
        },
        {
          "evidence_id": "E0011",
          "reason": "Post-inauguration energy framing is contextual rhetoric, not a direct existential-risk governance choice."
        },
        {
          "evidence_id": "E0012",
          "reason": "Diplomatic rhetoric on North Korea is relevant but should not be treated as structural nuclear-risk reform."
        },
        {
          "evidence_id": "E0013",
          "reason": "Launch of civil-nuclear cooperation talks is exploratory policy context, not evidence of safety or command-and-control improvement."
        },
        {
          "evidence_id": "E0014",
          "reason": "PNRI and partner commentary is administrative context rather than direct Marcos-directed existential-risk action."
        }
      ],
      "material_gaps": [
        {
          "gap": "No direct 2022 Marcos-attributed existential-risk choice, safeguard reform, or command-and-control decision is recoverable.",
          "lenses": ["1B.1", "1B.3", "1B.7", "1B.9", "1B.10"],
          "best_source_or_query_direction": "Official presidential directives, National Security Council or defense records, IAEA/UNODA filings, and cabinet appointment records tied to civil-nuclear or catastrophic-risk policy.",
          "why_it_matters": "Without a target-period choice, the chapter can only describe exposure and inherited constraints, not discriminate responsibility."
        },
        {
          "gap": "The package is heavy on nuclear-energy framing and treaty baseline, but thin on any ruler-attributed safety or precautionary implementation.",
          "lenses": ["1B.3", "1B.4", "1B.6", "1B.7", "1B.9"],
          "best_source_or_query_direction": "Presidential security appointments, IAEA interaction records, and any Marcos-era civil-nuclear implementation or dual-use governance documents.",
          "why_it_matters": "This is the boundary between a non-nuclear state with inherited treaties and a ruler who actually improved catastrophic-risk posture."
        }
      ],
      "reason": "The package is fair only as a limited-exposure/null chapter: it correctly shows a non-nuclear state with inherited treaty constraints and some civilian nuclear rhetoric, but it does not supply a Marcos-specific 2022 existential-risk decision strong enough to distinguish conduct from baseline."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0001",
          "reason": "Office-assumption evidence only; it establishes Marcos's entry into office, not peace or aggression conduct."
        },
        {
          "evidence_id": "E0002",
          "reason": "Constitutional authority is baseline context, not international-peace conduct."
        },
        {
          "evidence_id": "E0003",
          "reason": "Term limits are baseline context, not conduct evidence."
        },
        {
          "evidence_id": "E0018",
          "reason": "This captures a diplomatic meeting setting and Marcos's stated posture, but not a verified de-escalatory outcome."
        },
        {
          "evidence_id": "E0020",
          "reason": "Meeting tone with Xi is relevant but should not be overstated as a settlement or durable peace result."
        }
      ],
      "material_gaps": [],
      "reason": "The package is fair: it separates diplomacy from outcomes, preserves contrary evidence, and avoids attributing every South China Sea or regional tension to Marcos personally."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0029",
          "reason": "Pre-inauguration protest violence is transition context, not Marcos-ordered domestic-safety conduct."
        },
        {
          "evidence_id": "E0032",
          "reason": "This is a UN committee member's scrutiny question, not a judicial or investigative finding of a 78 percent increase."
        },
        {
          "evidence_id": "E0034",
          "reason": "The item mixes inherited Duterte-era violence with Marcos-era continuation; it should not be treated as cleanly Marcos-created harm."
        },
        {
          "evidence_id": "E0035",
          "reason": "SONA omission is relevant context, but silence is not the same as an explicit repression policy."
        }
      ],
      "material_gaps": [],
      "reason": "The package is fair despite relying on advocacy-heavy monitoring: it preserves attribution, context, and counterevidence while distinguishing inherited Duterte-era violence from Marcos-era continuation."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0036",
          "reason": "Formal proclamation records transfer into office, but not the depth of democratic contestability by itself."
        },
        {
          "evidence_id": "E0037",
          "reason": "Comelec's peaceful-election statement is useful context, not proof of broad political freedom."
        },
        {
          "evidence_id": "E0038",
          "reason": "Observer-mission reporting covers the election environment; it must not be read as a direct Marcos order for every abuse."
        },
        {
          "evidence_id": "E0040",
          "reason": "The DDoS attacks reflect the hostile information environment, but the item does not itself prove Marcos personally ordered the attacks."
        }
      ],
      "material_gaps": [],
      "reason": "The package is fair: it keeps campaign-period manipulation, press hostility, and formal transfer distinct, and it does not overread proclamation or peaceful-election claims as full democratic legitimacy."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0058",
          "reason": "This is structural World Bank baseline context that predates Marcos and should not be counted as his own performance."
        }
      ],
      "material_gaps": [],
      "reason": "The package is fair: it triangulates official macro series with independent IMF/World Bank context and clearly labels inherited shocks, while keeping causal attribution partial rather than overstated."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0075",
          "reason": "Inherited FY2022 budget is baseline context only; it predates Marcos's presidency."
        },
        {
          "evidence_id": "E0065",
          "reason": "WHO's vaccination-gap item is inherited health-system context, not Marcos-specific performance."
        },
        {
          "evidence_id": "E0069",
          "reason": "UNICEF's supportive framing is context, not an independent audit of Marcos-era welfare outcomes."
        },
        {
          "evidence_id": "E0099",
          "reason": "This DepEd item is only partially attributable to Marcos because the order is issued under Sara Duterte and broader pandemic reopening dynamics."
        }
      ],
      "material_gaps": [],
      "reason": "The package is fair, though thinner on measured outcomes than on intent and rollout: it shows welfare priorities, relief actions, and disaster response while acknowledging that durable outcome proof remains limited."
    },
    {
      "chapter_id": "7B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0079",
          "reason": "This is a retrospective ecosystem-level disinformation analysis; it is relevant context but not proof that Marcos personally ran each tactic."
        },
        {
          "evidence_id": "E0080",
          "reason": "The fact-check concerns family-history propaganda and campaign narrative, not a direct office-period act by Marcos himself."
        },
        {
          "evidence_id": "E0046",
          "reason": "Being the main beneficiary of disinformation is relevant but still indirect; it should not be treated as personal authorship of the propaganda."
        }
      ],
      "material_gaps": [
        {
          "gap": "No hard 2022 finding of personal self-enrichment, hidden assets, procurement conflict, or office misuse by Marcos is present.",
          "lenses": ["7B.3", "7B.4", "7B.6", "7B.7"],
          "best_source_or_query_direction": "SALN and asset-disclosure records, BIR/court files, COA audits, procurement records, and formal anti-corruption findings.",
          "why_it_matters": "Without a direct benefit or obstruction finding, the dossier rests mostly on false statements, appointments, and indirect pattern evidence."
        },
        {
          "gap": "Several of the strongest items are campaign-ecosystem or staffing-pattern evidence rather than clean office-period personal conduct.",
          "lenses": ["7B.1", "7B.2", "7B.5", "7B.10"],
          "best_source_or_query_direction": "Campaign-finance filings, platform-enforcement records, sworn statements, and documentary evidence tying specific actions directly to Marcos.",
          "why_it_matters": "This is the boundary between a personal-integrity dossier and a broader critique of the information environment and patronage network."
        }
      ],
      "reason": "The package is fair only as a partial personal-integrity dossier: it preserves specific false claims, family-interest tensions, and patronage-style staffing, but it still lacks the kind of hard finding that would make the chapter a fully secure office-period integrity case."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0001",
          "reason": "Inauguration evidence frames the start of the period, but it is not execution evidence."
        },
        {
          "evidence_id": "E0054",
          "reason": "Aggregate growth is useful outcome context, but attribution is mixed with reopening and base effects."
        },
        {
          "evidence_id": "E0055",
          "reason": "Inflation is an outcome indicator, but the causal share attributable to Marcos is partial and mixed with external shocks."
        },
        {
          "evidence_id": "E0056",
          "reason": "Labor-market recovery is relevant but still partly rebound-driven and not fully Marcos-specific."
        },
        {
          "evidence_id": "E0057",
          "reason": "Debt-ratio improvement is outcome context, but it is partly inherited and partly driven by growth/exchange-rate effects."
        },
        {
          "evidence_id": "E0064",
          "reason": "Long-run poverty history predates Marcos and should be treated as baseline, not execution."
        }
      ],
      "material_gaps": [],
      "reason": "The package is fair: it separates program articulation and staffing from outcomes, keeps moral judgment out of the competence lens, and labels the growth/inflation/debt evidence as mixed attribution rather than claiming full control."
    }
  ]
}
